SourceCode.Declaration:
/// <summary>
/// <c>METSOPrintDestinationContract</c> contract class to open common parameter and print destination dialog form
/// </summary>
[
    DataContractAttribute
]
class METSOPrintDestinationContract
{
    container       recordCon;
    boolean         usePrintMgmt;
    str             menuItemName;
    RefRecId        recordId;

}

Method.Source:
/// <summary>
/// container holds the list of records
/// </summary>
/// <param name = "_recordCon">container</param>
/// <returns>container</returns>
[DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)]
public container parmRecordCon(container _recordCon = recordCon)
{
    recordCon = _recordCon;

    return recordCon;
}

/// <summary>
/// parm method to get or set recordId
/// </summary>
/// <param name = "_recordId">RefRecId</param>
/// <returns>RefRecId</returns>
[DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)]
public RefRecId parmRecordId(RefRecId _recordId = recordId)
{
    recordId = _recordId;

    return recordId;
}

/// <summary>
/// MenuitemName
/// </summary>
/// <param name = "_menuItemName">str</param>
/// <returns>str</returns>
[DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)]
public str parmMenuItemName(str _menuItemName = menuItemName)
{
    menuItemName = _menuItemName;

    return menuItemName;
}

/// <summary>
/// method to set or get use print management
/// </summary>
/// <param name = "_usePrintMgmt">boolean</param>
/// <returns>boolean</returns>
[DataMemberAttribute, SysOperationLabel('@MET:UsePrintMgmt'),
    SysOperationControlVisibilityAttribute(true)]
public boolean parmUsePrintMgmt(boolean _usePrintMgmt = usePrintMgmt)
{
    usePrintMgmt = _usePrintMgmt;

    return usePrintMgmt;
}
